changeSet.sql:
UPDATE person_data_request SET state = 'PREVIEW', expires_at = LEAST(expires_at, CURRENT_TIMESTAMP) WHERE state = 'EXPIRED';
ALTER TABLE person_data_request DROP CONSTRAINT ck_person_data_request_state;
ALTER TABLE person_data_request ADD CONSTRAINT ck_person_data_request_state CHECK (state IN ('PREVIEW', 'ERASING', 'FAILED', 'COMPLETE'));
CREATE FUNCTION guard_person_data_request() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF OLD.state = 'COMPLETE' AND NEW.state IS DISTINCT FROM OLD.state THEN
  RAISE EXCEPTION 'a completed person data request keeps its state' USING ERRCODE = '55000';
 END IF;
 RETURN NULL;
END $$;
CREATE TRIGGER person_data_request_transition AFTER UPDATE OF state ON person_data_request FOR EACH ROW EXECUTE FUNCTION guard_person_data_request();

rollback.sql:
DROP TRIGGER person_data_request_transition ON person_data_request;
DROP FUNCTION guard_person_data_request();
ALTER TABLE person_data_request DROP CONSTRAINT ck_person_data_request_state;
ALTER TABLE person_data_request ADD CONSTRAINT ck_person_data_request_state CHECK (state IN ('PREVIEW', 'ERASING', 'FAILED', 'COMPLETE', 'EXPIRED'));
